import{_ as e,o as a,c as d,a2 as o}from"./chunks/framework.gtmkOXzY.js";const u=JSON.parse('{"title":"Companies","description":"","frontmatter":{},"headers":[],"relativePath":"ms-flightsim/companies.md","filePath":"ms-flightsim/companies.md","lastUpdated":null}'),r={name:"ms-flightsim/companies.md"};function n(i,t,l,s,h,c){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="companies" tabindex="-1">Companies <a class="header-anchor" href="#companies" aria-label="Permalink to &quot;Companies&quot;">​</a></h1><p>Every pilot works for one main company run by its captains, and any licensed pilot who owns an aircraft can also found a sub-company of their own.</p><h2 id="the-main-company" tabindex="-1">The main company <a class="header-anchor" href="#the-main-company" aria-label="Permalink to &quot;The main company&quot;">​</a></h2><h3 id="captains" tabindex="-1">Captains <a class="header-anchor" href="#captains" aria-label="Permalink to &quot;Captains&quot;">​</a></h3><p>A captain is a player on the pilot job at or above <code>Config.PilotAuthorization.captainGrade</code>. The shipped value is <code>3</code>. Set it to the top grade of your pilot job, or nobody can reach it.</p><p>Captains see a <strong>Company</strong> tab in the pilot tablet (<code>/pilottablet</code>). The tab follows the player&#39;s real pilot-job grade, so it also works in open-access mode for anyone you set to the pilot job at captain grade.</p><h3 id="what-captains-can-do" tabindex="-1">What captains can do <a class="header-anchor" href="#what-captains-can-do" aria-label="Permalink to &quot;What captains can do&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>How it works</th></tr></thead><tbody><tr><td>Company fund</td><td>See the balance and the transaction log</td></tr><tr><td>Withdraw</td><td>Take part or all of the fund into your bank</td></tr><tr><td>Hire</td><td>Enter an online player&#39;s server ID. They are set to the pilot job at grade 0.</td></tr><tr><td>Fire</td><td>Only pilots below your own grade. They are set to unemployed. Works on offline pilots too.</td></tr><tr><td>Promote or demote</td><td>Set a pilot&#39;s grade. Only to a grade below your own, and only for pilots below you.</td></tr><tr><td>Bonus</td><td>Pay an online pilot up to $100,000 from the fund. Not to yourself.</td></tr><tr><td>Set salaries</td><td>Set a salary per grade, from $0 to $50,000</td></tr><tr><td>Pay salaries</td><td>Pays every online pilot their grade&#39;s salary once, from the fund</td></tr></tbody></table><p>Salaries are only paid when a captain presses <strong>Pay salaries</strong>. Nothing is paid on a timer. If the fund cannot cover the total, nobody is paid.</p><h3 id="the-company-cut" tabindex="-1">The company cut <a class="header-anchor" href="#the-company-cut" aria-label="Permalink to &quot;The company cut&quot;">​</a></h3><p>10% of every legal job payout goes into the company fund. Set it with <code>Config.Payouts.companyCutPct</code> (<code>0.10</code>). Set it to <code>0</code> to turn the cut off.</p><ul><li>Smuggling is exempt, because it pays black money.</li><li>The cut is taken after all other pay multipliers and before the co-pilot split, so a two-pilot flight is cut once.</li></ul><h3 id="where-the-fund-lives-config-companybridge" tabindex="-1">Where the fund lives: <code>Config.CompanyBridge</code> <a class="header-anchor" href="#where-the-fund-lives-config-companybridge" aria-label="Permalink to &quot;Where the fund lives: `Config.CompanyBridge`&quot;">​</a></h3><table tabindex="0"><thead><tr><th><code>mode</code></th><th>Company tab</th><th>Company cut</th><th>Where the fund is</th></tr></thead><tbody><tr><td><code>&#39;internal&#39;</code> (default)</td><td>Shown</td><td>Taken</td><td>MS_FlightSim&#39;s own database table</td></tr><tr><td><code>&#39;society&#39;</code></td><td>Shown</td><td>Taken</td><td>An <code>esx_addonaccount</code> society account. Invoices paid through <code>esx_billing</code> land in the fund. Withdrawals, bonuses and salaries draw from it. ESX only.</td></tr><tr><td><code>&#39;external&#39;</code></td><td>Hidden</td><td>Still taken and logged</td><td>Your own boss menu handles hiring and the fund</td></tr><tr><td><code>&#39;disabled&#39;</code></td><td>Hidden</td><td>Not taken</td><td>No fund. Pilots keep 100% of their pay.</td></tr></tbody></table><p>Settings for <code>&#39;society&#39;</code> mode:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>societyAccount</code></td><td><code>&#39;society_pilot&#39;</code></td><td>The society account that holds the fund. Use <code>society_&lt;your pilot job&gt;</code>.</td></tr><tr><td><code>autoCreateSociety</code></td><td><code>true</code></td><td>Creates the account at start-up if it is missing</td></tr><tr><td><code>autoDetect</code></td><td><code>true</code></td><td>Prints known billing and banking resources found at start-up. It never changes the mode for you.</td></tr></tbody></table><p>In <code>&#39;external&#39;</code> and <code>&#39;disabled&#39;</code> modes the pilot-job grade still controls captain abilities everywhere else in the script.</p><h2 id="sub-companies" tabindex="-1">Sub-companies <a class="header-anchor" href="#sub-companies" aria-label="Permalink to &quot;Sub-companies&quot;">​</a></h2><p>A sub-company is your own small airline under the main company. You tag aircraft you own into its fleet, hire AI pilots, and send them out on real AI flights. The aircraft stay personally yours.</p><p>Open it from the <strong>Sub-Company</strong> tab in the pilot tablet.</p><h3 id="founding-one" tabindex="-1">Founding one <a class="header-anchor" href="#founding-one" aria-label="Permalink to &quot;Founding one&quot;">​</a></h3><p>You need:</p><ul><li>a plane or helicopter licence, and</li><li>at least one aircraft you own.</li></ul><p>Founding costs $25,000 (<code>Config.SubCompany.creationCost</code>). The name must be 3 to 32 characters. You can own one sub-company. Disbanding it removes every aircraft from the fleet but keeps them yours, and the founding fee is not refunded.</p><h3 id="levels" tabindex="-1">Levels <a class="header-anchor" href="#levels" aria-label="Permalink to &quot;Levels&quot;">​</a></h3><p>The company earns XP for each run it collects: 25 XP per run plus 0.01 XP per dollar of the run&#39;s pay. Levels raise how many aircraft, runs and pilots you can have. There are 20 levels.</p><table tabindex="0"><thead><tr><th>Level</th><th>Total XP</th><th>Fleet aircraft</th><th>Runs at once</th><th>Pilot seats</th></tr></thead><tbody><tr><td>1</td><td>0</td><td>2</td><td>1</td><td>1</td></tr><tr><td>3</td><td>689</td><td>3</td><td>1</td><td>1</td></tr><tr><td>4</td><td>1,121</td><td>3</td><td>1</td><td>2</td></tr><tr><td>5</td><td>1,583</td><td>4</td><td>2</td><td>2</td></tr><tr><td>7</td><td>2,575</td><td>5</td><td>2</td><td>3</td></tr><tr><td>9</td><td>3,637</td><td>6</td><td>3</td><td>3</td></tr><tr><td>10</td><td>4,189</td><td>6</td><td>3</td><td>4</td></tr><tr><td>13</td><td>5,917</td><td>8</td><td>3</td><td>5</td></tr><tr><td>16</td><td>7,734</td><td>9</td><td>3</td><td>6</td></tr><tr><td>17</td><td>8,357</td><td>10</td><td>3</td><td>6</td></tr><tr><td>19</td><td>9,626</td><td>10</td><td>3</td><td>7</td></tr><tr><td>20</td><td>10,271</td><td>10</td><td>3</td><td>7</td></tr></tbody></table><p>The fleet never goes above <code>maxFleet</code> (10) and runs at once never go above <code>dispatch.maxActive</code> (3). Set <code>levels.enabled = false</code> to give every company the full allowance from the start.</p><h3 id="fleet" tabindex="-1">Fleet <a class="header-anchor" href="#fleet" aria-label="Permalink to &quot;Fleet&quot;">​</a></h3><ul><li>Only fixed-wing aircraft can join a fleet. Helicopters cannot.</li><li>Only aircraft you own (not rented) can be added.</li><li>An aircraft out on a run cannot be retrieved, sold or sent again until it lands and is collected.</li></ul><h3 id="hiring-ai-pilots" tabindex="-1">Hiring AI pilots <a class="header-anchor" href="#hiring-ai-pilots" aria-label="Permalink to &quot;Hiring AI pilots&quot;">​</a></h3><p>A fleet aircraft needs a pilot assigned before it can fly a run. Each pilot flies one aircraft.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it means</th></tr></thead><tbody><tr><td>Applicants</td><td>4</td><td>Shown in the hiring pool, which changes every 30 minutes</td></tr><tr><td>Skill</td><td>1 to 5</td><td>Better pilots earn more per run and stay longer when idle</td></tr><tr><td>Hiring fee</td><td>skill × $9,000</td><td>Paid once from your money</td></tr><tr><td>Wage</td><td>skill × 2.5%</td><td>Taken from each run they fly. Never charged on a timer.</td></tr><tr><td>Pay bonus</td><td>skill × 5%</td><td>Added to each run they fly</td></tr><tr><td>Experience</td><td>12 XP per run</td><td>Every 120 XP raises their skill by 1, up to 5</td></tr></tbody></table><p><strong>Morale.</strong> Pilots start at 100 morale. After 12 hours without a run, morale starts to drop by 6 per hour, more slowly for higher skill. Each run restores 30. At 0 the pilot resigns. You cannot fire a pilot while their aircraft is in the air.</p><h3 id="maintenance" tabindex="-1">Maintenance <a class="header-anchor" href="#maintenance" aria-label="Permalink to &quot;Maintenance&quot;">​</a></h3><p>Each run uses the aircraft&#39;s own fuel and condition, the same values it has when you fly it yourself.</p><table tabindex="0"><thead><tr><th>Item</th><th>Default</th></tr></thead><tbody><tr><td>Fuel used by a 15-minute run</td><td>16% (longer runs use more)</td></tr><tr><td>Wear from a 15-minute run</td><td>5% (longer runs wear more)</td></tr><tr><td>Lowest fuel to send it out</td><td>15%</td></tr><tr><td>Lowest condition to send it out</td><td>25%</td></tr><tr><td>Refuel price</td><td>$14 per percent</td></tr><tr><td>Repair price</td><td>$95 per percent</td></tr></tbody></table><p>Refuel and repair from the tablet. You pay from your own money.</p><h3 id="dispatching-flights" tabindex="-1">Dispatching flights <a class="header-anchor" href="#dispatching-flights" aria-label="Permalink to &quot;Dispatching flights&quot;">​</a></h3><p>Pick a fleet aircraft with a pilot and a route, and send it.</p><table tabindex="0"><thead><tr><th>Route</th><th>From</th><th>To</th></tr></thead><tbody><tr><td>Short Haul</td><td>LSIA</td><td>Sandy Shores</td></tr><tr><td>Regional</td><td>LSIA</td><td>Grapeseed</td></tr><tr><td>Long Haul</td><td>LSIA</td><td>Cayo Perico</td></tr></tbody></table><ol><li>The run becomes a real AI flight. It departs the origin and lands at the destination in your aircraft model, painted your company colour.</li><li>Its callsign is built from your company name. For example, Mike Air Cargo flies as MAC123.</li><li>If you set a tail logo, the flight carries it.</li><li>You are told when it lands. Collect the pay in the tablet.</li></ol><p>How the pay is worked out:</p><ul><li>$55 per km flown, at least $150 per run.</li><li>+5% for every $100,000 the aircraft cost, up to +75%.</li><li>Each aircraft and route gets its own price within ±20%, changed every 15 minutes. The price shown in the tablet is what the run pays.</li><li>The pilot&#39;s pay bonus is added when the run is sent.</li></ul><p>At most 2 company flights are in the air at once across the server. If no AI slot is free, the run goes on a timetable instead and still pays. Runs to an airport in <code>Config.AITraffic.noAirports</code> (Grapeseed by default) always use the timetable.</p><p>If a live flight does not make it, it pays nothing and the aircraft comes back damaged.</p><h3 id="tail-logo" tabindex="-1">Tail logo <a class="header-anchor" href="#tail-logo" aria-label="Permalink to &quot;Tail logo&quot;">​</a></h3><p>Paste a FiveManage image link (https) into the Sub-Company tab. The logo shows on fleet aircraft the next time they leave the hangar, and on every company flight. Leave the field empty to remove it.</p><h3 id="franchise-cut" tabindex="-1">Franchise cut <a class="header-anchor" href="#franchise-cut" aria-label="Permalink to &quot;Franchise cut&quot;">​</a></h3><p>Headquarters takes 15% (<code>franchiseCut</code>) of:</p><ul><li>every collected run, and</li><li>your share of any paid job you fly yourself in a fleet aircraft.</li></ul><p>It goes into the main company fund. This is on top of the main <a href="#the-company-cut">company cut</a>.</p><h3 id="leaderboard" tabindex="-1">Leaderboard <a class="header-anchor" href="#leaderboard" aria-label="Permalink to &quot;Leaderboard&quot;">​</a></h3><p>The tablet shows the top 10 sub-companies by gross earnings (<code>leaderboardTop</code>).</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>/subco create &lt;name&gt;</code></td><td>Found a sub-company</td></tr><tr><td><code>/subco rename &lt;name&gt;</code></td><td>Rename it</td></tr><tr><td><code>/subco fleet</code></td><td>Show your earnings and owned aircraft, with their IDs</td></tr><tr><td><code>/subco assign &lt;id&gt;</code></td><td>Add an owned aircraft to the fleet</td></tr><tr><td><code>/subco unassign &lt;id&gt;</code></td><td>Remove it from the fleet</td></tr><tr><td><code>/subco board</code></td><td>Show the leaderboard</td></tr><tr><td><code>/subco disband</code></td><td>Close the sub-company</td></tr><tr><td><code>subcodiag</code> <em>(server console)</em></td><td>Checks the sub-company database tables. Use it when the Sub-Company tab says the server did not respond.</td></tr></tbody></table>',56)])])}const f=e(r,[["render",n]]);export{u as __pageData,f as default};
